class Solution {
public:
    int distinctAverages(vector<int>& nums) {
        int freq[101] = {0};
        for (int x : nums) freq[x]++;
        bool seen[201] = {false};
        int lo = 0, hi = 100, count = 0;
        int pairs = (int)nums.size() / 2;
        while (pairs--) {
            while (freq[lo] == 0) lo++;
            while (freq[hi] == 0) hi--;
            int s = lo + hi;
            if (!seen[s]) { seen[s] = true; count++; }
            freq[lo]--; freq[hi]--;
        }
        return count;
    }
};
